import React from 'react';
import { StyleSheet, View, Text, TouchableOpacity, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const ShiftCard = ({ shift }) => {
  const renderEmployees = () => {
    const visibleEmployees = shift.employees.slice(0, 3);
    const remainingCount = shift.additionalCount || 0;

    return (
      <View style={styles.employeesContainer}>
        <View style={styles.employeeAvatars}>
          {visibleEmployees.map((employee, index) => (
            <Image
              key={employee.id}
              source={{ uri: employee.avatar }}
              style={styles.employeeAvatar}
            />
          ))}
          {remainingCount > 0 && (
            <View style={styles.additionalCount}>
              <Text style={styles.additionalCountText}>+{remainingCount}</Text>
            </View>
          )}
        </View>
      </View>
    );
  };

  const renderStatus = () => {
    if (shift.status === 'missing') {
      return (
        <View style={styles.statusContainer}>
          <Ionicons name="add" size={12} color="#F44336" />
          <Text style={styles.missingText}>{shift.missingText}</Text>
        </View>
      );
    }
    
    if (shift.task) {
      return (
        <View style={styles.statusContainer}>
          <Ionicons name="calendar" size={12} color="#666666" />
          <Text style={styles.taskText}>{shift.task}</Text>
        </View>
      );
    }
    
    return null;
  };

  return (
    <TouchableOpacity style={[styles.card, { backgroundColor: shift.backgroundColor }]}>
      <View style={[styles.cardContent, { backgroundColor: shift.backgroundColor }]}>
        {/* Icon and Title */}
        <View style={styles.headerSection}>
          <View style={[styles.iconContainer, { backgroundColor: shift.iconColor }]}>
                 <Ionicons 
                   name={shift.iconName} 
                   size={10} 
                   color="#FFFFFF" 
                 />
          </View>
          <Text style={styles.shiftTitle}>{shift.title}</Text>
        </View>

        {/* Bỏ hiển thị giờ */}

        {/* Employees */}
        {renderEmployees()}

        {/* Status/Task */}
        {renderStatus()}
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  card: {
    borderRadius: 4, // Google Calendar rounded corners
    marginBottom: 1, // Google Calendar tight spacing
    padding: 6, // Google Calendar compact padding
    // Google Calendar clean borders
    borderLeftWidth: 3,
    borderLeftColor: '#20B2AA', // Google Calendar accent color
    // Card dimensions
    flex: 1,
    minHeight: 40, // Google Calendar compact height
    // No blur effects
    opacity: 1,
    backdropFilter: 'none',
    filter: 'none',
    // Layer trên cùng
    zIndex: 999999,
    elevation: 999999,
    // Google Calendar subtle shadow
    boxShadow: '0 1px 2px rgba(0, 0, 0, 0.1)',
    // Solid background
    backgroundColor: '#FFFFFF',
  },
  cardContent: {
    flex: 1,
    // Không có hiệu ứng mờ
    opacity: 1,
    // Đảm bảo nền rõ ràng và che phủ các đường kẻ
    backgroundColor: '#FFFFFF', // Solid white background
    // Đảm bảo che phủ hoàn toàn
    width: '100%',
    height: '100%',
    position: 'relative',
    zIndex: 1000000, // Cao hơn card - nổi lên trên
  },
  headerSection: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 2,
  },
  iconContainer: {
    width: 16, // Google Calendar compact icon
    height: 16,
    borderRadius: 8,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 4, // Google Calendar tight spacing
  },
  shiftTitle: {
    fontSize: 11, // Google Calendar compact font size
    fontWeight: '500', // Google Calendar font weight
    color: '#3C4043', // Google Calendar text color
    flex: 1,
    opacity: 1,
    textShadow: 'none',
    lineHeight: 14, // Google Calendar line height
    // Google Calendar typography
    fontFamily: 'Roboto, sans-serif',
  },
  timeText: {
    fontSize: 9, // Google Calendar compact time font
    color: '#5F6368', // Google Calendar secondary text
    marginBottom: 2, // Google Calendar tight spacing
    opacity: 1,
    textShadow: 'none',
    lineHeight: 12, // Google Calendar line height
    // Google Calendar typography
    fontFamily: 'Roboto, sans-serif',
  },
  employeesContainer: {
    marginBottom: 6, // Tăng spacing như trong ảnh
  },
  employeeAvatars: {
    flexDirection: 'column', // Xếp chồng thành cột dọc
    alignItems: 'flex-start',
    justifyContent: 'flex-start',
  },
  employeeAvatar: {
    width: 16, // Size như trong ảnh
    height: 16,
    borderRadius: 8,
    borderWidth: 2,
    borderColor: '#FFFFFF',
    // Avatars xếp chồng như trong ảnh
    marginLeft: -4, // Overlap như trong ảnh
  },
  additionalCount: {
    width: 16, // Size như trong ảnh
    height: 16,
    borderRadius: 8,
    backgroundColor: '#CCCCCC',
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#FFFFFF',
    // Overlap như avatar
    marginLeft: -4,
  },
  additionalCountText: {
    fontSize: 6, // Google Calendar compact text
    fontWeight: 'bold',
    color: '#666666',
  },
  statusContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginTop: 2, // Spacing như trong ảnh
  },
  missingText: {
    fontSize: 9, // Size như trong ảnh
    color: '#F44336',
    fontWeight: '500',
    marginLeft: 4, // Spacing như trong ảnh
  },
  taskText: {
    fontSize: 9, // Size như trong ảnh
    color: '#666666',
    marginLeft: 4, // Spacing như trong ảnh
  },
});

export default ShiftCard;
